public static final class Gate {
    private final java.util.concurrent.CompletableFuture<Void> opened = new java.util.concurrent.CompletableFuture<>();
    private final java.util.concurrent.CompletableFuture<Void> waiting = new java.util.concurrent.CompletableFuture<>();
    public void open() { opened.complete(null); }
    public java.util.concurrent.CompletionStage<Void> waiting() { return waiting; }
    private void await(io.github.diodeme.ji.ai.CancellationToken cancellation) {
        waiting.complete(null);
        opened.applyToEither(cancellation.cancellation().toCompletableFuture(), ignored -> null).join();
    }
}
